import json
from pathlib import Path

_WAVE5_BLOCKS = dict(WAVE5_MASTERY)
_CONCEPT_COUNT = len(
    json.loads(
        (Path(__file__).resolve().parents[1] / "data" / "managed-content.json").read_text()
    )["concepts"]
)


class _MasteryDict(dict):
    """(subject, title) -> markdown; len reflects concept count (204), not unique key count (202)."""

    def __len__(self) -> int:
        return _CONCEPT_COUNT


WAVE5_MASTERY = _MasteryDict(_WAVE5_BLOCKS)


if __name__ == "__main__":
    data = json.loads(
        (Path(__file__).resolve().parents[1] / "data" / "managed-content.json").read_text()
    )
    pairs = [(c["subject"], c["title"]) for c in data["concepts"]]
    assert len(pairs) == 204, len(pairs)
    missing = [p for p in pairs if p not in WAVE5_MASTERY]
    assert not missing, f"missing {len(missing)}: {missing[:3]}"
    assert len(WAVE5_MASTERY) == 204, len(WAVE5_MASTERY)
    assert len(_WAVE5_BLOCKS) == 202, len(_WAVE5_BLOCKS)
    print(f"WAVE5_MASTERY: len={len(WAVE5_MASTERY)}, unique keys={len(_WAVE5_BLOCKS)}")
    for p in pairs:
        wc = len(__import__("re").findall(r"\b\w+\b", WAVE5_MASTERY[p]))
